{"content": "# -*- coding: utf-8 -*-
"""
固定燃烧源（火电热力 POWER）排放清单编制 — 通用工具调用型 Agent
Run package: R3 (C-75-POW-GEN-R3)

处理逻辑（全部基于运行包内输入 + T/CSES 144-2024 PDF 建立）：
  1) 源分类判定（全部 4442 条候选）：
       POWER     : 基102 行业类别代码 ∈ {4411 火力发电, 4412 热电联产,
                    4417 生物质能发电, 4430 热力生产和供应}   (PDF §7.1)
       INDUSTRIAL: 行业代码前缀 ∈ 采矿业06-12 / 制造业13-43 / 燃气生产供应45 (PDF §8.1)
       OUT_OF_SCOPE: 其余（4419 其他电力生产、46 水的生产、05 农业等）
    仅对 POWER 源核算排放（run_manifest target=POWER）。
  2) 排放核算（PDF §7.2 公式(2) E=A×EF×(1−η)）：
       - A: 燃料消耗量（固体/液体 吨→kg；气体 万立方米→m3）
       - EF: 表D.1 系数；煤炭/煤矸石 SO2、PM2.5、PM10、BC、OC 用物料衡算
            公式(3)-(6)+表C.1~C.3；电力生产燃煤 NOx 按装机容量(表D.1注b)
       - η: 治理设施实际去除效率（基101-2002 去除效率；缺失时按处理工艺
             回退表A.1；无治理取0）。低氮燃烧按表A.1 22%（无脱硝设施时）
  3) 每个燃料/组件在三个 *_record_json 数组中各占一个元素，component_id 对齐。
"""
import json
import os
import sys
import math

import pandas as pd

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ef_tables import (D1, C1, C2, C3, A1, NOX_CAP, POLLUTANTS,
                       DESULFUR_PROC_MAP, DEDUST_PROC_MAP)

R3 = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/075%规模/02_火电热力/03_通用工具调用型Agent/R3"
INPUTS = os.path.join(R3, "inputs")
OUT = os.path.join(R3, "outputs")
WORK = os.path.join(R3, "work")

POWER_CODES = {"4411", "4412", "4417", "4430"}

# ---------------------------------------------------------------------------
# 1. Load inputs
# ---------------------------------------------------------------------------
b102 = pd.read_excel(os.path.join(INPUTS, "基102-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
b101c = pd.read_excel(os.path.join(INPUTS, "基101-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
index_data = json.load(open(os.path.join(INPUTS, "source_identity_index.json"), encoding="utf-8"))
manifest = json.load(open(os.path.join(R3, "run_manifest.json"), encoding="utf-8"))

rec_by_sid = {r["source_id"]: r for r in index_data["records"]}
candidate_ids = manifest["candidate_ids"]
assert len(candidate_ids) == len(b102) == 4442, (len(candidate_ids), len(b102))

# row index of 基102 DataFrame (0-based) for a source_row (1-based incl header)
def row_idx(source_row):
    return int(source_row) - 2

# ---------------------------------------------------------------------------
# 2. Classification of every candidate
# ---------------------------------------------------------------------------
def classify(industry_code):
    c = str(industry_code)
    if c in POWER_CODES:
        return "POWER", "TARGET_INDUSTRY_" + c
    prefix2 = c[:2]
    try:
        p = int(prefix2)
    except ValueError:
        p = -1
    if 6 <= p <= 12 or 13 <= p <= 43 or p == 45:
        return "INDUSTRIAL", "INDUSTRIAL_INDUSTRY_" + c
    return "OUT_OF_SCOPE", "OUT_OF_SCOPE_INDUSTRY_" + c

# ---------------------------------------------------------------------------
# 3. Enterprise key (credit code preferred, org code fallback) and boiler-code
# ---------------------------------------------------------------------------
def ek_of(series_credit, series_org):
    c = series_credit
    o = series_org
    if pd.notna(c) and str(c).strip() != "":
        return ("C", str(c))
    if pd.notna(o) and str(o).strip() != "":
        return ("O", str(o))
    return ("N", None)

b102["_ek"] = b102.apply(lambda r: ek_of(r["统一社会信用代码"], r["组织机构代码"]), axis=1)
b101c["_ek"] = b101c.apply(lambda r: ek_of(r["统一社会信用代码"], r["组织机构代码"]), axis=1)
b102["_is_zb"] = b102["电站锅炉/燃气轮机编号"].notna()
b102["_boiler_code"] = b102["_is_zb"].map(lambda t: "DZGL" if t else "GYGL")

# control facilities matched per (ek, boiler_code)
ctl = b101c[b101c["对应的排放口代码"].isin(["DZGL", "GYGL"])].copy()
ctl_groups = {}
for (ek, code), g in ctl.groupby(["_ek", "对应的排放口代码"]):
    ctl_groups[(ek, code)] = g

FAC_TYPES = {"脱硫（酸）设施": "SO2", "脱硝设施": "NOx", "除尘设施": "PM", "挥发性有机物治理设施": "VOC"}

def proc_fallback(fac_name, proc):
    """去除效率缺失时按处理工艺名称回退表A.1默认效率。返回 (dict per pollutant) 或 None。"""
    if fac_name == "脱硫（酸）设施":
        for key, a1name in DESULFUR_PROC_MAP:
            if key in proc:
                row = A1[a1name]
                return {"SO2": row[0]}
        if "脱硫" in proc or "脱酸" in proc:
            return {"SO2": A1["其他脱硫技术"][0]}
        return None
    if fac_name == "除尘设施":
        for key, a1name in DEDUST_PROC_MAP:
            if key in proc:
                row = A1[a1name]
                return {"PM_fine": row[3], "PM_coarse": row[4]}
        return {"PM_fine": A1["其他除尘技术"][3], "PM_coarse": A1["其他除尘技术"][4]}
    if fac_name == "脱硝设施":
        if "选择性催化还原" in proc or "SCR" in proc.upper():
            return {"NOx": A1["选择性催化还原法"][1]}
        if "选择性非催化还原" in proc or "SNCR" in proc.upper():
            return {"NOx": A1["选择性非催化还原法"][1]}
        if "低氮燃烧" in proc:
            return {"NOx": A1["低氮燃烧技术"][1]}
        return {"NOx": A1["其他脱硝技术"][1]}
    if fac_name == "挥发性有机物治理设施":
        for key, a1name in [("蓄热式热力燃烧", "蓄热式热力燃烧法"), ("蓄热式催化燃烧", "蓄热式热力燃烧法"),
                            ("吸附/催化燃烧", "吸附/催化燃烧法"), ("催化燃烧", "催化燃烧法"),
                            ("活性炭", "活性炭法"), ("沸石转轮", "沸石转轮吸附法"),
                            ("低温等离子体", "低温等离子体"), ("光解", "光解"), ("光催化", "光催化"),
                            ("冷凝", "冷凝法"), ("生物过滤", "生物过滤法"), ("热力燃烧", "热力燃烧"),
                            ("直接燃烧", "热力燃烧"), ("吸附", "活性炭法"), ("吸收", "其他脱硫技术")]:
            if key in proc:
                return {"VOC": A1[a1name][2]}
        return {"VOC": A1["其他除尘技术"][2]} if False else None
    return None

def control_eta(row):
    """
    返回 (eta, flags): eta 为每污染物去除效率字典; flags 记录信息不足原因
    eta keys: SO2, NOx, VOC, fine, coarse, BC, OC, CO, NH3
    """
    key = (row["_ek"], row["_boiler_code"])
    g = ctl_groups.get(key)
    eta = {"SO2": 0.0, "NOx": 0.0, "VOC": 0.0, "fine": 0.0, "coarse": 0.0,
           "BC": 0.0, "OC": 0.0, "CO": 0.0, "NH3": 0.0}
    flags = []
    if g is None or len(g) == 0:
        return eta, flags
    for fac_name, pol in FAC_TYPES.items():
        sub = g[g["废气治理设施名称"] == fac_name]
        if len(sub) == 0:
            continue
        effs = sub["去除效率（%）"].dropna()
        if len(effs) > 0:
            r = float(effs.max()) / 100.0
            if pol == "SO2":
                eta["SO2"] = max(eta["SO2"], r)
            elif pol == "NOx":
                eta["NOx"] = max(eta["NOx"], r)
            elif pol == "PM":
                eta["fine"] = max(eta["fine"], r)
                eta["coarse"] = max(eta["coarse"], r)
                eta["BC"] = max(eta["BC"], r)
                eta["OC"] = max(eta["OC"], r)
            elif pol == "VOC":
                eta["VOC"] = max(eta["VOC"], r)
            continue
        # no reported efficiency -> try A.1 fallback by process name
        procs = sub["处理工艺名称"].dropna()
        if len(procs) > 0:
            fb = None
            for p in procs:
                v = proc_fallback(fac_name, str(p))
                if v is not None:
                    if fb is None:
                        fb = {}
                    for k, vv in v.items():
                        fb[k] = max(fb.get(k, 0.0), float(vv) / 100.0)
            if fb is not None:
                if pol == "SO2":
                    eta["SO2"] = max(eta["SO2"], fb["SO2"])
                elif pol == "NOx":
                    eta["NOx"] = max(eta["NOx"], fb["NOx"])
                elif pol == "PM":
                    eta["fine"] = max(eta["fine"], fb["PM_fine"])
                    eta["coarse"] = max(eta["coarse"], fb["PM_coarse"])
                    eta["BC"] = max(eta["BC"], fb["PM_fine"])
                    eta["OC"] = max(eta["OC"], fb["PM_fine"])
                elif pol == "VOC":
                    eta["VOC"] = max(eta["VOC"], fb["VOC"])
                continue
        # facility exists but neither efficiency nor recognizable process
        flags.append("CONTROL_NO_PERFORMANCE_DATA_" + fac_name)
    # low-NOx combustion (表A.1 低氮燃烧技术 22%) — only when no denitration facility efficiency used
    lnb_col = "是否采用低氮燃烧技术" if row["_is_zb"] else "是否采用低氮燃烧技术.1"
    lnb = row.get(lnb_col)
    has_denit_eff = False
    if g is not None:
        dsub = g[g["废气治理设施名称"] == "脱硝设施"]
        has_denit_eff = (len(dsub) > 0 and dsub["去除效率（%）"].notna().any())
    if eta["NOx"] == 0.0 and not has_denit_eff:
        if pd.notna(lnb) and str(lnb).strip() == "是":
            eta["NOx"] = 0.22
    return eta, flags

# ---------------------------------------------------------------------------
# 4. Fuel components & EF
# ---------------------------------------------------------------------------
GAS_UNIT = "万立方米"
SOLID_LIQ_UNITS = {"吨", "t"}

def comp_activity(value, unit):
    """return (A_mass_kg, A_vol_m3, gas_flag, unit_label)"""
    if unit == GAS_UNIT:
        return None, float(value) * 1e4, True, unit
    if unit in SOLID_LIQ_UNITS:
        return float(value) * 1000.0, None, False, unit
    if unit == "吨标准煤":
        return None, None, False, unit
    return None, None, False, unit

COAL_TECH = {
    "煤粉炉": "煤粉炉",
    "循环流化床锅炉": "流化床炉",
    "链条炉": "自动炉排层燃炉",
    "其他层燃炉": "自动炉排层燃炉",
    "抛煤机炉": "自动炉排层燃炉",
    "层燃炉": "自动炉排层燃炉",
}
GAS_FUELS_AS_GAS = {"天然气", "焦炉煤气", "高炉煤气", "其它煤气", "转炉煤气", "其它气体燃料"}
LNG_LPG = {"液化天然气", "液化石油气"}

def fuel_to_d1_name(fuel):
    if fuel in ("一般烟煤", "原煤", "无烟煤", "褐煤"):
        return "煤炭"
    return fuel

def sector_of(code):
    return "电力生产" if str(code) in ("4411", "4412", "4417") else "热力生产和供应"

def device_type_of(row):
    if row["_is_zb"]:
        return row["电站锅炉/燃气轮机类型"]
    return row["工业锅炉类型"]

def combustion_tech_of(row):
    if row["_is_zb"]:
        return row["电站锅炉燃烧方式"]
    return row["工业锅炉燃烧方式"]

def nox_by_capacity(cap_mw):
    for upper, ef in NOX_CAP:
        if float(cap_mw) <= upper:
            return ef
    return NOX_CAP[-1][1]

def component_ef(row, sector, fuel, tech_key, d1_name):
    """
    Returns (ef_map, reason) where ef_map: pollutant -> value or "MB" marker
    tech_key: combustion tech string for D.1 (e.g. 煤粉炉/燃气锅炉/燃油锅炉/不分技术)
    reason: None if ok else short code
    """
    dev = device_type_of(row)
    # device-type coverage: D.1 only defines 燃气锅炉/燃油锅炉/煤粉炉/流化床炉/自动炉排层燃炉/不分技术
    if fuel in ("城市生活垃圾（用于燃料）",):
        return None, "EF_UNAVAILABLE_MSW"
    if fuel == "生物燃料":
        return None, "EF_UNAVAILABLE_BIOMASS"
    if fuel == "其他燃料":
        return None, "EF_UNAVAILABLE_OTHER_FUEL"
    if fuel == "工业废料（用于燃料）":
        return None, "EF_UNAVAILABLE_INDUSTRIAL_WASTE"
    if fuel == "煤制品":
        return None, "EF_UNAVAILABLE_COAL_PRODUCT"
    if dev in ("燃气轮机", "余热利用锅炉"):
        return None, "EF_UNAVAILABLE_DEVICE_" + dev
    d1_name = fuel_to_d1_name(fuel)
    if d1_name not in D1[sector]:
        return None, "EF_UNAVAILABLE_FUEL_" + fuel
    tech_rows = D1[sector][d1_name]
    if tech_key not in tech_rows:
        # fuel1 天然气 on 燃生物质锅炉 etc. -> technology mismatch
        return None, "TECH_NOT_COVERED_" + tech_key
    return tech_rows[tech_key], None

def coal_mb_ef(sector, tech, sulfur_pct, ash_pct):
    """物料衡算 公式(3)-(6): returns dict of EF per pollutant (g/kg)"""
    sr, ar = C1[sector][tech]
    f25, f10 = C2[sector][tech]
    fbc, foc = C3[sector][tech]
    ef_so2 = 2.0 * float(sulfur_pct) * (1.0 - sr)
    ef_pm25 = float(ash_pct) * (1.0 - ar) * f25
    ef_pm10 = float(ash_pct) * (1.0 - ar) * f10
    ef_bc = ef_pm25 * fbc
    ef_oc = ef_pm25 * foc
    return {"SO2": ef_so2, "PM2.5": ef_pm25, "PM10": ef_pm10, "BC": ef_bc, "OC": ef_oc}

# ---------------------------------------------------------------------------
# 5. Per-candidate inventory building
# ---------------------------------------------------------------------------
def build_components(row):
    """Return list of component dicts: id, fuel, value, unit, is_gas, kind"""
    comps = []
    f1 = row["燃料一类型"]
    if pd.notna(f1) and str(f1).strip() != "":
        comps.append({"id": "F1", "fuel": str(f1),
                      "value": float(row["燃料一消耗量"]), "unit": str(row["燃料一消耗量单位"])})
    f2 = row["燃料二类型"]
    if pd.notna(f2) and str(f2).strip() != "" and pd.notna(row["燃料二消耗量"]):
        comps.append({"id": "F2", "fuel": str(f2),
                      "value": float(row["燃料二消耗量"]), "unit": str(row["燃料二消耗量单位"])})
    oth = row["其他燃料消耗总量（吨标准煤）"]
    if pd.notna(oth) and float(oth) > 0:
        comps.append({"id": "F3", "fuel": "其他燃料（吨标准煤）", "value": float(oth), "unit": "吨标准煤"})
    return comps

def compute_component_pollutants(row, comp, sector):
    """
    Returns per-pollutant dict: pollutant -> {ef, ef_mode, ef_unit, status, reason}
    status: "ok" or "insufficient" (EF level)
    """
    fuel = comp["fuel"]
    unit = comp["unit"]
    value = comp["value"]
    out = {}
    # unit handling
    if unit == "吨标准煤":
        for p in POLLUTANTS:
            if p == "NH3":
                out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
            else:
                out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                          "reason": "FUEL_UNIT_TCE_NO_EF"}
        return out
    is_gas_unit = (unit == GAS_UNIT)
    if not is_gas_unit and unit not in SOLID_LIQ_UNITS:
        for p in POLLUTANTS:
            if p == "NH3":
                out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
            else:
                out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                          "reason": "FUEL_UNIT_UNKNOWN_" + str(unit)}
        return out

    dev = device_type_of(row)
    tech_raw = combustion_tech_of(row)
    sector = sector_of(row["行业类别代码"])

    # gas fuels: D.1 row is per m3, technology must be 燃气锅炉 (or 不分技术? none for gas)
    if fuel in GAS_FUELS_AS_GAS or fuel in LNG_LPG:
        if dev not in ("燃气锅炉",):
            reason = "EF_UNAVAILABLE_DEVICE_" + str(dev) if dev in ("燃气轮机", "余热利用锅炉") else "TECH_NOT_COVERED_" + str(dev)
            for p in POLLUTANTS:
                if p == "NH3":
                    out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                else:
                    out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient", "reason": reason}
            return out
        d1_name = fuel_to_d1_name(fuel)
        row_ef = D1[sector].get(d1_name, {}).get("燃气锅炉")
        if row_ef is None:
            for p in POLLUTANTS:
                if p == "NH3":
                    out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                else:
                    out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                              "reason": "EF_UNAVAILABLE_FUEL_" + fuel}
            return out
        ef_unit = "g/m3"
        for p in POLLUTANTS:
            if p == "NH3":
                out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                continue
            ef = row_ef.get(p)
            if ef is None or ef == "MB":
                out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                          "reason": "EF_MB_NOT_APPLICABLE_GAS"}
            else:
                out[p] = {"ef": float(ef), "ef_mode": "table_D1", "ef_unit": ef_unit, "status": "ok"}
        return out

    # solid/liquid fuels (吨)
    d1_name = fuel_to_d1_name(fuel)
    if d1_name in ("煤炭", "煤矸石"):
        tech = COAL_TECH.get(tech_raw)
        if tech is None:
            # cannot pick ar/f or D.1 row without combustion technology
            for p in POLLUTANTS:
                if p == "NH3":
                    out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                else:
                    out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                              "reason": "COMBUSTION_TECH_UNKNOWN_" + str(tech_raw)}
            return out
        row_ef = D1[sector].get(d1_name, {}).get(tech if d1_name == "煤炭" else "不分技术")
        if row_ef is None:
            for p in POLLUTANTS:
                if p == "NH3":
                    out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                else:
                    out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                              "reason": "EF_UNAVAILABLE_FUEL_" + fuel}
            return out
        # coal material balance inputs
        s_col = "燃料一平均收到基含硫量" if comp["id"] == "F1" else "燃料二平均收到基含硫量"
        a_col = "燃料一平均收到基灰分（%）" if comp["id"] == "F1" else "燃料二平均收到基灰分（%）"
        s_val = row[s_col]
        a_val = row[a_col]
        if pd.isna(s_val) or pd.isna(a_val):
            for p in POLLUTANTS:
                if p == "NH3":
                    out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                else:
                    out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                              "reason": "FUEL_QUALITY_MISSING_" + ("S" if pd.isna(s_val) else "ASH")}
            return out
        mb = coal_mb_ef(sector, tech, float(s_val), float(a_val))
        if sector == "电力生产" and d1_name in ("煤炭", "煤矸石"):
            ef_nox = nox_by_capacity(row["对应机组装机容量（万千瓦）"]) if pd.notna(row["对应机组装机容量（万千瓦）"]) else None
            if ef_nox is None:
                for p in POLLUTANTS:
                    if p == "NH3":
                        out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
                    else:
                        out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                                  "reason": "CAPACITY_MISSING_NOX"}
                return out
        else:
            ef_nox = row_ef["NOx"]
        for p in POLLUTANTS:
            if p == "NH3":
                out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
            elif p == "SO2":
                out[p] = {"ef": mb["SO2"], "ef_mode": "material_balance", "ef_unit": "g/kg", "status": "ok"}
