            elif p == "CO":
                out[p] = {"ef": float(row_ef["CO"]), "ef_mode": "table_D1", "ef_unit": "g/kg", "status": "ok"}
            elif p == "VOC":
                out[p] = {"ef": float(row_ef["VOCs"]), "ef_mode": "table_D1", "ef_unit": "g/kg", "status": "ok"}
        return out

    # other solid/liquid fuels -> D.1 燃油锅炉 rows
    row_ef = D1[sector].get(d1_name, {}).get("燃油锅炉")
    if row_ef is None:
        for p in POLLUTANTS:
            if p == "NH3":
