    for p in POLLUTANTS:
        if p == "NH3":
            out[p] = {"ef": 0.0, "ef_mode": "method_zero", "ef_unit": "g/kg", "status": "ok"}
        elif p in row_ef and row_ef[p] != "MB":
            out[p] = {"ef": float(row_ef[p]), "ef_mode": "table_D1", "ef_unit": "g/kg", "status": "ok"}
        else:
            out[p] = {"ef": None, "ef_mode": None, "ef_unit": None, "status": "insufficient",
                      "reason": "EF_MB_NOT_APPLICABLE_" + fuel}
    return out

def build_inventory_row(row, source_id):
    sector = sector_of(row["行业类别代码"])
    comps = build_components(row)
    eta, flags = control_eta(row)
    # pollutant-level control insufficiency flags
    ctl_flags = {}
    for f in flags:
        if "脱硫" in f:
            ctl_flags.setdefault("SO2", []).append(f)
        elif "脱硝" in f:
            ctl_flags.setdefault("NOx", []).append(f)
        elif "除尘" in f:
            ctl_flags.setdefault("PM", []).append(f)
            ctl_flags.setdefault("BC", []).append(f)
            ctl_flags.setdefault("OC", []).append(f)
        elif "挥发性有机物" in f:
            ctl_flags.setdefault("VOC", []).append(f)

    comp_results = []
    for comp in comps:
        per_p = compute_component_pollutants(row, comp, sector)
        comp_results.append({"comp": comp, "per_p": per_p})

    items = []
    for p in POLLUTANTS:
        gen_total = 0.0
        emi_total = 0.0
        all_ok = True
        reasons = []
        act_records = []
        par_records = []
        ctl_records = []
        for cr in comp_results:
            comp = cr["comp"]
            cid = comp["id"]
            info = cr["per_p"][p]
            # activity record
            act_records.append({"component_id": cid, "value": comp["value"], "unit": comp["unit"]})
            # parameter & control record
            if info["status"] == "ok":
                ef = info["ef"]
                par_records.append({"component_id": cid, "parameter_id": "EF_" + p,
                                    "mode": info["ef_mode"], "value": ef, "unit": info["ef_unit"]})
            else:
                all_ok = False
                reasons.append(info.get("reason", "EF_MISSING"))
                par_records.append({"component_id": cid, "parameter_id": "EF_" + p,
                                    "mode": "unavailable", "value": None, "unit": ""})
            # control record per component (same boiler-level eta)
            if p == "PM10":
                ctl_records.append({"component_id": cid, "method": "除尘设施" if eta["fine"] > 0 or eta["coarse"] > 0 else "none",
                                    "efficiency": round(eta["fine"], 6),
                                    "fine_efficiency": round(eta["fine"], 6),
                                    "coarse_efficiency": round(eta["coarse"], 6)})
            else:
                eff = {"SO2": eta["SO2"], "NOx": eta["NOx"], "CO": 0.0, "VOC": eta["VOC"],
                       "PM2.5": eta["fine"], "PM10": eta["fine"], "BC": eta["BC"], "OC": eta["OC"],
                       "NH3": 0.0}[p]
                ctl_records.append({"component_id": cid, "method": "none" if eff == 0 else "control",
                                    "efficiency": round(eff, 6),
                                    "fine_efficiency": round(eta["fine"], 6),
                                    "coarse_efficiency": round(eta["coarse"], 6)})
            # compute if ok
            if info["status"] == "ok":
                if comp["unit"] == GAS_UNIT:
                    a_factor = 1e4  # 万立方米 -> m3
                    ef = info["ef"]
                    gen = float(comp["value"]) * a_factor * ef * 1e-6
                else:
                    ef = info["ef"]
                    gen = float(comp["value"]) * 1000.0 * ef * 1e-6
                if p == "PM10":
                    pm25 = cr["per_p"]["PM2.5"]
                    pm10 = info
                    ef25 = pm25["ef"] if pm25["status"] == "ok" else 0.0
                    ef10 = pm10["ef"]
                    if comp["unit"] == GAS_UNIT:
                        gen25 = float(comp["value"]) * 1e4 * ef25 * 1e-6
                        gen10 = float(comp["value"]) * 1e4 * ef10 * 1e-6
                    else:
                        gen25 = float(comp["value"]) * 1000.0 * ef25 * 1e-6
                        gen10 = float(comp["value"]) * 1000.0 * ef10 * 1e-6
                    gen_total += gen10
                    emi_total += gen25 * (1 - eta["fine"]) + (gen10 - gen25) * (1 - eta["coarse"])
                else:
                    gen_total += gen
                    emi_total += gen * (1 - {"SO2": eta["SO2"], "NOx": eta["NOx"], "CO": 0.0, "VOC": eta["VOC"],
                                             "PM2.5": eta["fine"], "PM10": eta["fine"],
                                             "BC": eta["BC"], "OC": eta["OC"], "NH3": 0.0}[p])
        # control insufficiency
        for pol_key, fl in ctl_flags.items():
            if (p == "PM10" and pol_key == "PM") or p == pol_key or (p in ("BC", "OC") and pol_key == "PM") or (p == "PM2.5" and pol_key == "PM"):
                if all_ok:
                    all_ok = False
                    reasons.extend(fl)
        if not all_ok:
            status = "information_insufficient"
        else:
            status = "calculated"
        if p == "NH3":
            # NH3 has method EF=0 for all components; always calculated
            if status == "information_insufficient":
                reasons = [r for r in reasons if r != "EF_MISSING"]
            status = "calculated"
        # round values
        gen_total = round(gen_total, 6)
        emi_total = round(emi_total, 6)
        if status == "calculated":
            gv, ev = gen_total, emi_total
        else:
            gv, ev = None, None
        reason_code = ";".join(sorted(set(reasons))) if status != "calculated" else ""
        std_ref = standard_reference(p, comp_results)
        items.append({
            "source_id": source_id,
            "target": "POWER",
            "pollutant": p,
            "status": status,
            "method": method_label(p, comp_results),
            "activity_record_json": json.dumps(act_records, ensure_ascii=False),
            "parameter_record_json": json.dumps(par_records, ensure_ascii=False),
            "control_record_json": json.dumps(ctl_records, ensure_ascii=False),
            "generation_t": gv,
            "emission_t": ev,
            "standard_reference": std_ref,
            "reason_code": reason_code,
        })
    return items

def standard_reference(p, comp_results):
    modes = set()
    for cr in comp_results:
        info = cr["per_p"][p]
        if info["status"] == "ok":
            modes.add(info["ef_mode"])
    if "material_balance" in modes:
        if p in ("SO2",):
            return "T/CSES 144-2024 公式(3)+表C.1"
        if p in ("PM2.5", "PM10", "BC", "OC"):
            return "T/CSES 144-2024 公式(4)~(6)+表C.1~C.3"
    if "capacity_based" in modes:
        return "T/CSES 144-2024 表D.1 注b"
    if "method_zero" in modes and len(modes) == 1:
        return "T/CSES 144-2024 §7.2（电力热力源无NH3核算路径，EF=0）"
    return "T/CSES 144-2024 公式(2)+表D.1"

def method_label(p, comp_results):
    modes = set()
    for cr in comp_results:
        info = cr["per_p"][p]
        if info["status"] == "ok":
            modes.add(info["ef_mode"])
    if "material_balance" in modes:
        return "material_balance_method"
    if "method_zero" in modes and len(modes) == 1:
        return "zero_method"
    return "emission_factor_method"

# ---------------------------------------------------------------------------
# 6. Run
# ---------------------------------------------------------------------------
os.makedirs(OUT, exist_ok=True)
os.makedirs(WORK, exist_ok=True)

decisions = []
inventory_items = []
dispositions = []
exceptions = []
exception_seen = {}

def add_exception(root_cause, source_id, pollutant, action):
    key = root_cause
    if key not in exception_seen:
        exception_seen[key] = {"exception_id": "EXC-%03d" % (len(exception_seen) + 1),
                               "source_id": source_id, "pollutant": pollutant,
                               "root_cause": root_cause, "action_required": action}
    else:
        exception_seen[key]["source_id"] = exception_seen[key]["source_id"] + ";" + source_id

n_power = 0
for sid in candidate_ids:
    rec = rec_by_sid[sid]
    r = b102.iloc[row_idx(rec["source_row"])]
    ind = r["行业类别代码"]
    decided, rc = classify(ind)
    disp = {"POWER": "included", "INDUSTRIAL": "excluded_industrial", "OUT_OF_SCOPE": "excluded_out_of_scope"}[decided]
    decisions.append({"source_id": sid, "requested_target": "POWER", "decided_target": decided,
                      "disposition": disp, "reason_code": rc})
    dispositions.append({"source_id": sid, "target": "POWER", "disposition": disp, "reason_code": rc})
    if decided == "POWER":
        n_power += 1
        items = build_inventory_row(r, sid)
        for it in items:
            inventory_items.append(it)
            if it["status"] == "information_insufficient":
                root = it["reason_code"].split(";")[0] if it["reason_code"] else "UNKNOWN"
                if root.startswith("CONTROL_NO_PERFORMANCE_DATA"):
                    root_cause = "治理设施（" + root.replace("CONTROL_NO_PERFORMANCE_DATA_", "") + "）存在但去除效率与处理工艺均缺失"
                    action = "补充该治理设施实际去除效率或处理工艺名称，或提供设施运行时间以计算投运率"
                elif root.startswith("EF_UNAVAILABLE"):
                    fuel_or_dev = root.replace("EF_UNAVAILABLE_", "")
                    root_cause = "燃料/设备类型无产生系数：" + fuel_or_dev
                    action = "从生态环境部公告2021年第24号系数手册或实测法获取" + fuel_or_dev + "的产生系数后补算"
                elif root.startswith("TECH_NOT_COVERED") or root.startswith("COMBUSTION_TECH_UNKNOWN"):
