                else:
                    root_cause = "其他信息不足：" + root
                    action = "补充缺失的活动水平/系数/治理信息后重算"
                add_exception(root_cause, sid, it["pollutant"], action)

print("decisions:", len(decisions), "| power:", n_power, "| inventory items:", len(inventory_items))
